<section class="admin-panel upload-panel"><div><p class="eyebrow">MEDIA LIBRARY</p><h2>Tambah dokumentasi</h2><p class="admin-muted">Format JPG, PNG, atau WebP. File asli maksimal 20 MB per gambar. Sistem mengoptimasi gambar dengan sasaran hasil simpan di bawah 1 MB. Gunakan foto yang telah mendapat izin publikasi.</p></div><?php if ($canEdit): ?><form method="post" action="/admin/media/unggah" enctype="multipart/form-data" class="media-upload-form"><?= csrf_field() ?><label>File gambar<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><label>Teks alternatif<input name="alt_text" maxlength="255" placeholder="Deskripsikan isi gambar"></label><label class="checkbox-line"><input type="checkbox" name="is_gallery" value="1"> Tampilkan di galeri publik</label><button class="button button-primary" type="submit">Unggah gambar</button></form><?php endif; ?></section>
<section class="media-library-section"><div class="admin-panel-heading"><div><p class="eyebrow">KOLEKSI FILE</p><h2><?= count($items) ?> file tersimpan</h2></div></div><?php if ($items): ?><div class="media-admin-grid"><?php foreach ($items as $item): ?><article class="media-admin-card"><img src="<?= e('/' . $item['file_path']) ?>" alt="<?= e($item['alt_text']) ?>"><div><strong><?= e($item['alt_text'] ?: $item['original_name']) ?></strong><small><?= e(number_format((int)$item['file_size']/1024, 0, ',', '.')) ?> KB · <?= e(format_date($item['created_at'])) ?></small><div class="media-admin-actions"><form method="post" action="/admin/media/<?= (int)$item['id'] ?>/galeri"><?= csrf_field() ?><button type="submit"><?= (int)$item['is_gallery'] ? 'Hapus dari galeri' : 'Tampilkan di galeri' ?></button></form><?php if (in_array($user['role'], ['super_admin','editor'], true)): ?><form method="post" action="/admin/media/<?= (int)$item['id'] ?>/hapus" data-confirm="Hapus file ini? File yang digunakan konten tidak dapat dihapus."><?= csrf_field() ?><button class="text-danger" type="submit">Hapus</button></form><?php endif; ?></div></div></article><?php endforeach; ?></div><?php else: ?><div class="table-empty"><strong>Belum ada media.</strong><span>Unggah foto sekolah yang telah diverifikasi untuk digunakan pada berita dan galeri.</span></div><?php endif; ?></section>
